function numDecodings(s) {
  const memo = {};

  const dfs = (i) => {
    if (i === s.length) return 1;
    if (memo[i] !== undefined) return memo[i];

    let ways = 0;
    if (s[i] !== '0') {
      ways += dfs(i + 1);
    }
    if (i + 1 < s.length) {
      const twoDigit = parseInt(s.substring(i, i + 2));
      if (twoDigit >= 10 && twoDigit <= 26) {
        ways += dfs(i + 2);
      }
    }

  };
}
